candidate_lemmas.statement:
private theorem ramanujan_mul (F G : SelbergClass) (ε : ℝ) (hε : 0 < ε) :
    ∃ C : ℝ, 0 < C ∧ ∀ n : ℕ, n ≠ 0 →
      ‖(F.coeff * G.coeff) n‖ ≤ C * (n : ℝ) ^ ε

